                cycle.push_back(i);
                if(i > 1) cycle.push_back(n);
            }
        }
        long long total = n * n - n + 1;
        l--, r--;
        long long start = l % (total - 1);
        vector<long long> result;
        for(long long i=0; i<r-l+1; i++){
            result.push_back(cycle[(start + i) % (total - 1)]);
        }
        for(auto &x: result) cout << x << " ";
        cout << "\n";
    }
}

