#include <bits/stdc++.h>
using namespace std;

int dx[] = {0, 0, 1, -1};
int dy[] = {1, -1, 0, 0};

bool canReach(vector<vector<char>>& grid, int n, int val) {
    queue<pair<int, int>> q;
    vector<vector<bool>> vis(n, vector<bool>(n, false));
    q.push({0, 0});
    vis[0][0] = true;

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        if (x == n - 1 && y == n - 1) return true;

        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !vis[nx][ny]) {
                if (nx == 0 && ny == 0) {
                    q.push({nx, ny});
                    vis[nx][ny] = true;
                } else if (nx == n - 1 && ny == n - 1) {
                    q.push({nx, ny});
                    vis[nx][ny] = true;
                } else {
                    if (grid[nx][ny] - '0' == val) {
                        q.push({nx, ny});
                        vis[nx][ny] = true;
                    }
                }
            }
        }
    }
    return false;
}

