            std::vector<double> roots = {root1, root2};
            std::sort(roots.begin(), roots.end());
            std::cout << 2 << std::endl;
            std::cout << std::fixed << std::setprecision(10) << roots[0] << std::endl;
            std::cout << std::fixed << std::setprecision(10) << roots[1];
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj;
vector<bool> visited;
double expect;

void calculate(int v, int size) {
    visited[v] = true;
    int sum = 0;
    vector<int> component_sizes;
    for (int u : adj[v]) {
        if (!visited[u]) {
            visited[u] = true;
            int comp_size = 1;
            stack<int> s;
            s.push(u);
            while (!s.empty()) {
                int x = s.top();
                s.pop();
                for (int w : adj[x]) {
                    if (!visited[w]) {
                        visited[w] = true;
                        s.push(w);
                        comp_size++;
                    }
                }
            }
            component_sizes.push_back(comp_size);
            sum += comp_size;
        }
    }
    expect += size;
    for (int comp_size : component_sizes) {
        calculate(u, comp_size);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    adj.resize(n);
    for (int i = 0; i < n; ++i) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    visited.assign(n, false);
    expect = 0.0;
    calculate(0, n);
    cout << fixed << setprecision(15) << expect / n;
    return 0;
}

