void dfs(int u, int p, long long d) {
    distToRoot[u] = d;
    visited[u] = true;
    for (auto [v, w] : adj[u]) {
        if (v != p) {
            dfs(v, u, d + w);
        }
    }
}

void hld_dfs(int u, int chainNum, int chainHead, int d, int heavy) {
    visited[u] = true;
    ans[u][0] = chainHead;
    ans[u][1] = chainNum;
    ans[u][2] = d;
    if (heavy != -1) {
        hld_dfs(heavy, chainNum, chainHead, d, -1);
    }
    for (auto [v, w] : adj[u]) {
        if (!visited[v]) {
            hld_dfs(v, chainNum + 1, v, 0, -1);
        }
    }
}

long long powMod(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp % 2 == 1) {
            res = (res * base) % MOD;
        }
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

