const ll MOD = 1e9 + 7;

ll modpow(ll base, ll exp) {
    ll res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

bool subset(const set<ll>& small, const set<ll>& large) {
    for (ll x : small) {
        if (large.find(x) == large.end()) return false;
    }
    return true;
}

