        clear_dsu();
        for(int i = 0; i < m; i++){
            if(i < l - 1 || i > r - 1){
                join(sorted_edges[i].first.first, sorted_edges[i].first.second, i);
            }
        }
        priority_queue<long long> pq;
        for(int i = 1; i <= n; i++){
            if(dsu[i].second != -1){
                pq.push(edges[dsu[i].second].second);
            }
        }
        if(pq.empty()){
            cout << -1 << "\n";
        }
        else{
            cout << pq.top() << "\n";
        }
