}

#include <bits/stdc++.h>
using namespace std;

int rev(int x) {
    int ans = 0;
    while (x > 0) {
        ans = ans * 10 + x % 10;
        x /= 10;
    }
    return ans;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int maxx, maxy, w;
    cin >> maxx >> maxy >> w;
    int cnt = 0;
    int ansx = -1, ansy = -1;
    for(int x = 1; x <= maxx; x++){
        for(int y = 1; y <= maxy; y++){
            if(1LL * x * y > 1e9) continue;
            if(x * y == rev(x) * rev(y)){
                cnt++;
            }
            if(cnt >= w){
                ansx = x;
                ansy = y;
                break;
            }
        }
        if(cnt >= w) break;
    }
    if(ansx == -1) cout << "-1\n";
    else cout << ansx << " " << ansy << "\n";
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for(auto &x: a) cin >> x;
    for(auto &x: b) cin >> x;

    vector<pair<int, int>> ab(n);
    for(int i=0;i<n;i++) ab[i] = {a[i], b[i]};

    sort(ab.begin(), ab.end(), [&](auto &x, auto &y){
        return x.second - x.first > y.second - y.first;
    });

    priority_queue<int> pq;
    int time = 0, used = 0;

    for(auto &[ai, bi]: ab){
        int space = bi - ai;
        while(!pq.empty() && space > 0){
            int x = min(space, -pq.top());
            time += x;
            space -= x;
            int y = pq.top(); pq.pop();
            y += x;
            if(y < 0) pq.push(y);
        }
        if(space > 0){
            pq.push(-space);
            used++;
        }
    }

    cout << used + pq.size() << " " << time;
}

