bool isZigzag(const string& num) {
    int n = num.size();
    if (n == 1) return true;
    bool up = num[1] > num[0];
    for (int i = 1; i < n - 1; ++i) {
        if ((up && num[i + 1] <= num[i]) || (!up && num[i + 1] >= num[i])) {
            up = !up;
        } else {
            return false;
        }
    }
    return true;
}

