bool isValidShortPhrase(const vector<int>& wordLengths, int start) {
    if (start + 9 > wordLengths.size()) return false;
    int sections[5] = {5, 7, 5, 7, 7};
    int index = 0;
    for (int i = 0; i < 5; ++i) {
