vector<vector<int>> adj;
vector<int> depth;
vector<int> leaf_count;

void dfs(int u, int d) {
    depth[u] = d;
    if (adj[u].size() == 0) {
        leaf_count[u] = 1;
        return;
    }
    for (int v : adj[u]) {
        dfs(v, d + 1);
        leaf_count[u] += leaf_count[v];
    }
}

int main() {
