vector<vector<int>> generate_permutations(const vector<int>& p, int c) {
    int n = p.size();
    set<vector<int>> s;
    for (int l = 0; l < n; ++l) {
        for (int r = l; r < n; ++r) {
            if (r - l <= c) {
                vector<int> curr = p;
                reverse(curr.begin() + l, curr.begin() + r + 1);
                s.insert(curr);
            }
        }
    }
    return vector<vector<int>>(s.begin(), s.end());
}

