string a, b, c;
int countOccurrences(const string& text, const string& pattern) {
    int count = 0;
    size_t pos = text.find(pattern);
    while (pos != string::npos) {
        count++;
        pos = text.find(pattern, pos + 1);
    }
    return count;
}

bool canFormStringWithPattern(string& a, const string& pattern, int occurrenceCount) {
    int currCount = 0;
    for (int i = 0; i <= (int)a.size() - (int)pattern.size() && currCount < occurrenceCount; ++i) {
        if (a.substr(i, pattern.size()) == string(pattern.size(), '?')) {
            a.replace(i, pattern.size(), pattern);
            currCount++;
        }
    }
    return currCount == occurrenceCount;
}

int main(){
    cin >> a >> b >> c;
    int maxB = countOccurrences(a, b);
    int maxC = countOccurrences(a, c);

    int totalLength = a.size();
    string tempA = a;
    int bCount = 0, cCount = 0;

    for (int i = maxB; i >= 0; --i) {
        int remainingLength = totalLength - (i * b.size());
        int possibleCCount = remainingLength / c.size();
        possibleCCount = min(possibleCCount, maxC);

        tempA = a;
        if (canFormStringWithPattern(tempA, b, i) && canFormStringWithPattern(tempA, c, possibleCCount)) {
            bCount = i;
            cCount = possibleCCount;
            break;
        }
    }

    for (int i = 0; i < (int)a.size();) {
        if (bCount > 0 && a.substr(i, b.size()) == string(b.size(), '?')) {
            cout << b;
            i += b.size();
            bCount--;
        } else if (cCount > 0 && a.substr(i, c.size()) == string(c.size(), '?')) {
            cout << c;
            i += c.size();
            cCount--;
        } else {
            cout << a[i];
            i++;
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

double min_weakness(vector<int>& a) {
    int n = a.size();
    double left = -1e4, right = 1e4;
    for (int iter = 0; iter < 100; ++iter) {
        double mid1 = left + (right - left) / 3;
        double mid2 = right - (right - left) / 3;
        double max_poorness1 = 0, max_poorness2 = 0;
        double current_sum1 = 0, current_sum2 = 0;
        double min_prefix_sum1 = 0, min_prefix_sum2 = 0;
        for (int i = 0; i < n; ++i) {
            current_sum1 += a[i] - mid1;
            current_sum2 += a[i] - mid2;
            max_poorness1 = max(max_poorness1, abs(current_sum1 - min_prefix_sum1));
            max_poorness2 = max(max_poorness2, abs(current_sum2 - min_prefix_sum2));
            min_prefix_sum1 = min(min_prefix_sum1, current_sum1);
            min_prefix_sum2 = min(min_prefix_sum2, current_sum2);
        }
        if (max_poorness1 < max_poorness2) {
            right = mid2;
        } else {
            left = mid1;
        }
    }
    return left;
}

