        long long start = max(i * i, (l + i - 1) / i * i);
        for(long long j = start; j <= r; j += i){
            if(j >= l){
                count[i]++;
            }
        }
    }

    long long max_count = 0, result = 0;
    for(const auto& [key, value] : count){
        if(value > max_count || (value == max_count && key < result)){
            max_count = value;
            result = key;
        }
    }

    cout << result;
}

