const int MAXN = 25;
const double EPS = 1e-9;

int a[MAXN];

double check(double max_ratio) {
    vector<double> b;
    for (int i = 0; i < N; i++) {
        double lo = a[i] * (1 - max_ratio);
        double hi = a[i] * (1 + max_ratio);
        if (b.empty()) {
            b.push_back(lo);
        } else {
            if (b.back() + EPS > hi) return 1e9;
            lo = max(lo, b.back() + EPS);
            b.push_back(lo);
        }
    }
    for (int i = 1; i < N; i++) {
        if (fabs(fmod(b[i], b[i-1])) > EPS) return 1e9;
    }
    return b[N-1];
}

