bool canCoexist(const string& s, const string& r1, const string& r2, const string& r3) {
    int n = s.size();
    int i1 = 0, i2 = 0, i3 = 0;

    for (char c : s) {
        if (i1 < r1.size() && c == r1[i1]) i1++;
        if (i2 < r2.size() && c == r2[i2]) i2++;
        if (i3 < r3.size() && c == r3[i3]) i3++;
    }

    return i1 == r1.size() && i2 == r2.size() && i3 == r3.size();
}

