                x_changes[y_map[a.y1]].emplace_back(x1, -1);
            }else{
                x_changes[y_map[a.y0]].emplace_back(x1, 1);
                x_changes[y_map[a.y1]].emplace_back(x0, -1);
            }
        }
    }
    for(auto &v: x_changes){
        sort(v.begin(), v.end());
        int sum = 0;
        for(auto &p: v){
            p.second += sum;
            sum = p.second;
        }
    }
    for(auto &v: y_changes){
        sort(v.begin(), v.end());
        int sum = 0;
        for(auto &p: v){
            p.second += sum;
            sum = p.second;
        }
    }
    while(q--){
