typedef long long ll;
const int MOD = 1000000007;
const int MAX = 21; // 2^20 = 1048576 > 10^6

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> a(n);
    for(int &x : a) cin >> x;

    vector<ll> dp(1<<MAX, 0);
    dp[0] = 1;
    for(int mask = 0; mask < (1<<MAX); ++mask){
        for(int x : a){
            int newMask = mask & ~x;
            dp[mask] = (dp[mask] + dp[newMask]) % MOD;
        }
    }

    ll result = dp[(1<<MAX)-1];
    cout << result << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    string s;
    cin >> s;
    int n = s.size();
    vector<int> ans;
    int open = 0, close = 0, hash = 0;
    for(char c : s){
        if(c == '(') open++;
        else if(c == ')') close++;
        else hash++;
    }
    if(open != close + hash){
        cout << -1;
        return 0;
    }
    int curr_open = 0;
    bool valid = true;
    for(char c : s){
        if(c == '('){
            curr_open++;
        }
        else if(c == ')'){
            curr_open--;
            if(curr_open < 0){
                valid = false;
                break;
            }
        }
        else{
            int need = open - curr_open - (hash-1);
            if(need <= 0 || curr_open + need > open){
                valid = false;
                break;
            }
            ans.push_back(need);
            curr_open += need;
            hash--;
        }
    }
    if(!valid || curr_open != open){
        cout << -1;
    }
    else{
        for(int x : ans){
            cout << x << "\n";
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

bool check(vector<ll>& a, int k) {
    for (int i = 0; i < (int)a.size() - k + 1; ++i) {
        if (a[i] >= a[i + 1]) return false;
    }
    return true;
}

void solve() {
    int n, k;
    cin >> n >> k;
    vector<string> s(n);
    for (auto& x : s) cin >> x;
    vector<ll> a(n, 0), fixed(n, 0);
    queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (s[i] == "?") {
            q.push(i);
        } else {
            a[i] = stoll(s[i]);
            fixed[i] = 1;
        }
    }
    vector<ll> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + a[i];
    bool valid = true;
    while (!q.empty() && valid) {
        int cur = q.front();
        q.pop();
        if (cur >= k) {
            if (fixed[cur - k]) {
                a[cur] = a[cur - k] + 1 - (pref[cur] - pref[cur - k]);
                if (a[cur] < -1e9) valid = false;
            }
        }
        if (cur + 1 < n) {
            if (fixed[cur + 1]) {
                a[cur] = a[cur + 1] - 1 - (pref[cur + 1] - pref[cur]);
                if (a[cur] < -1e9) valid = false;
            }
        }
        if (cur >= k && cur + 1 < n) {
            a[cur] = max(a[cur], pref[cur] - pref[cur - k] + 1);
            a[cur] = min(a[cur], pref[cur + 1] - pref[cur] - 1);
            if (a[cur] < -1e9 || a[cur] > 1e9) valid = false;
        }
        pref[cur + 1] = pref[cur] + a[cur];
        if (cur + 2 >= k) {
            valid &= check(a, k);
        }
    }
    if (!valid || !check(a, k)) {
        cout << "Incorrect sequence";
        return;
    }
    for (auto x : a) {
        cout << x << " ";
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    solve();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, m;
vector<string> s;
vector<vector<int>> cost;
int dp[1<<20][21][21];

int solve(int mask, int pos, int last) {
    if (mask == (1<<n) - 1) return 0;
    if (pos == m) return 1e9;
    int &ret = dp[mask][pos][last];
    if (ret != -1) return ret;
    ret = 1e9;
    vector<int> cnt(26, 0);
    for (int i = 0; i < n; ++i) {
        if (!(mask & (1<<i))) {
            cnt[s[i][pos] - 'a']++;
        }
    }
    for (int i = 0; i < n; ++i) {
        if (mask & (1<<i)) continue;
        if (cnt[s[i][pos] - 'a'] == 1 && s[i][pos] - 'a' != last) {
            ret = min(ret, solve(mask | (1<<i), pos, s[i][pos] - 'a'));
        }
    }
    for (int c = 0; c < 26; ++c) {
        if (c == last) continue;
        int new_mask = mask;
        int total_cost = 0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1<<i)) continue;
            if (s[i][pos] - 'a' == c) {
                new_mask |= (1<<i);
            } else {
                total_cost += cost[i][pos];
            }
        }
        ret = min(ret, total_cost + solve(new_mask, pos + 1, c));
    }
    return ret;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m;
    s.resize(n);
    for (auto &x : s) cin >> x;
    cost.resize(n, vector<int>(m));
    for (auto &v : cost) {
        for (auto &x : v) cin >> x;
    }
    memset(dp, -1, sizeof(dp));
    cout << solve(0, 0, 26) << "\n";
}

