int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n);
    for(int i=0;i<m;i++){
        int u, v;
        cin >> u >> v;
        u--, v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<int> color(n, -1);
    queue<int> q;
    vector<int> set1, set2;
    bool bipartite = true;
    for(int i=0;i<n;i++){
        if(color[i] == -1){
            color[i] = 0;
            q.push(i);
            while(!q.empty()){
                int node = q.front();
                q.pop();
                if(color[node] == 0){
                    set1.push_back(node);
                }else{
                    set2.push_back(node);
                }
                for(auto &neigh : adj[node]){
                    if(color[neigh] == -1){
                        color[neigh] = 1 - color[node];
                        q.push(neigh);
                    }else if(color[neigh] == color[node]){
                        bipartite = false;
                        break;
                    }
                }
                if(!bipartite){
                    break;
                }
            }
        }
        if(!bipartite){
            break;
        }
    }
    if(!bipartite){
        cout << "-1\n";
        return 0;
    }
    bool set1_valid = true, set2_valid = true;
    for(int i=0;i<n && (set1_valid || set2_valid);i++){
        if(adj[i].empty()){
            continue;
        }
        bool found1 = false, found2 = false;
        for(auto &neigh : adj[i]){
            if(find(set1.begin(), set1.end(), neigh) != set1.end()){
                found1 = true;
            }
            if(find(set2.begin(), set2.end(), neigh) != set2.end()){
                found2 = true;
            }
            if(found1 && found2){
                break;
            }
        }
        if(!found1){
            set1_valid = false;
        }
        if(!found2){
            set2_valid = false;
        }
    }
    if(set1_valid && set2_valid){
        cout << set1.size() << "\n";
        for(auto &x : set1){
            cout << x + 1 << " ";
        }
        cout << "\n";
        cout << set2.size() << "\n";
        for(auto &x : set2){
            cout << x + 1 << " ";
        }
        cout << "\n";
    }else{
        cout << "-1\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 400010;

vector<int> adj[MAXN];
int subTreeSize[MAXN];
bool centroid[MAXN];
int n, parent[MAXN];

void dfs(int u, int p) {
    parent[u] = p;
    subTreeSize[u] = 1;
    for (int v : adj[u]) {
        if (v != p) {
            dfs(v, u);
            subTreeSize[u] += subTreeSize[v];
        }
    }
}

int findCentroid(int u, int size, int p) {
    for (int v : adj[u]) {
        if (v != p && !centroid[v] && subTreeSize[v] > size / 2) {
            return findCentroid(v, size, u);
        }
    }
    return u;
}

void decompose(int u, int p) {
    dfs(u, -1);
    int c = findCentroid(u, subTreeSize[u], -1);
    centroid[c] = true;
    for (int v : adj[c]) {
        if (!centroid[v]) {
            decompose(v, c);
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n;
    for(int i=0;i<n-1;i++){
        int u,v;
        cin >> u >> v;
        u--, v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    decompose(0, -1);
    vector<int> result(n, 0);
    for(int i=0;i<n;i++){
        int maxSize = 0;
        for(int v : adj[i]){
            if(!centroid[v]){
                maxSize = max(maxSize, subTreeSize[v]);
            }
        }
        maxSize = max(maxSize, n - subTreeSize[i]);
        if(maxSize <= (n+1)/2){
            result[i] = 1;
        }
    }
    for(int i=0;i<n;i++){
        cout << result[i] << " ";
    }
    cout << "\n";
    return 0;
}

