void bfs(int start, int dist[]) {
    queue<pair<int, int>> q;
    q.push({start, 0});
    fill(dist, dist + n + 1, INF);
    dist[start] = 0;
    while (!q.empty()) {
        auto [node, d] = q.front();
        q.pop();
        for (auto [next, w] : adj[node]) {
            if (dist[next] > d + w) {
                dist[next] = d + w;
                q.push({next, d + w});
            }
        }
    }
}

