#include <bits/stdc++.h>
using namespace std;

const int MAXN = 2e5 + 100;
vector<int> adj[MAXN];
int pos[MAXN], comp[MAXN], cyc[MAXN], len[MAXN], endc[MAXN];
int dp[MAXN][40];

void dfs(int u, int p, int& count, int root) {
    if (comp[u] != -1) {
        if (u == root) {
            cyc[u] = 1;
            len[u] = 0;
            pos[u] = count;
            comp[u] = root;
            return;
        } else {
            int cur = p, steps = 0;
            while (cur != u) {
                cyc[cur] = 2;
                steps++;
                cur = adj[cur][0];
            }
            cyc[u] = 2;
            len[u] = steps + 1;
            cur = u;
            steps = 0;
            while (pos[cur] == -1) {
                pos[cur] = count - steps;
                steps++;
                cur = adj[cur][0];
            }
            comp[u] = comp[cur];
            endc[root] = u;
        }
    } else {
        comp[u] = root;
        pos[u] = count++;
        dfs(adj[u][0], u, count, root);
        if (cyc[u] == 2 && u == root) {
            int cur = u;
            do {
                cyc[cur] = 1;
                cur = adj[cur][0];
            } while (cur != u);
        }
    }
}

void init_lca(int u, int p) {
    dp[u][0] = p;
    for (int i = 1; i < 40; ++i) {
        dp[u][i] = dp[dp[u][i - 1]][i - 1];
    }
    for (auto v : adj[u]) {
        init_lca(v, u);
    }
}

int lca(int u, int v) {
    if (pos[u] > pos[v]) swap(u, v);
    for (int i = 39; i >= 0; --i) {
        if (pos[dp[v][i]] >= pos[u]) {
            v = dp[v][i];
        }
    }
    if (u == v) return u;
    for (int i = 39; i >= 0; --i) {
        if (dp[u][i] != dp[v][i]) {
            u = dp[u][i];
            v = dp[v][i];
        }
    }
    return dp[u][0];
}

int main(){
    ios::sync_with_stdio(false);
