        adj[i].push_back(x);
    }
    fill(comp, comp + MAXN, -1);
    fill(pos, pos + MAXN, -1);
    for(int i=1; i<=n; ++i){
        if(comp[i] == -1){
            int count = 0;
            dfs(i, 0, count, i);
        }
    }
    init_lca(1, 0);
    int q;
    cin >> q;
    while(q--){
        long long m;
        int y;
        cin >> m >> y;
        int start = y;
        int u = y;
        if(cyc[u] == 2){
            long long steps = m;
            if(steps < len[u]){
                for(int i=39; i>=0; --i){
                    if((1LL << i) <= steps){
                        u = adj[u][i];
                        steps -= (1LL << i);
                    }
                }
            } else {
                steps -= len[u];
                u = endc[comp[u]];
                steps %= len[u];
                for(int i=39; i>=0; --i){
                    if((1LL << i) <= steps){
                        u = adj[u][i];
                        steps -= (1LL << i);
                    }
                }
            }
            cout << (u == start) << "\n";
        } else {
            long long steps = m;
            if(cyc[u]){
                steps -= pos[u];
                steps %= len[u];
                u = endc[comp[u]];
                steps += pos[u];
            }
            for(int i=39; i>=0; --i){
                if((1LL << i) <= steps){
                    u = adj[u][i];
                    steps -= (1LL << i);
                }
            }
            int res = 0;
            if(cyc[u]){
                if(cyc[start] && comp[start] == comp[u]){
                    int LCA = lca(u, start);
                    res = len[comp[u]] - abs(pos[u] - pos[start]);
                    res += abs(pos[LCA] - pos[start]);
                    res += abs(pos[LCA] - pos[u]);
                } else {
                    if(start == u) res++;
                }
            } else {
                if(start == u) res++;
            }
            cout << res << "\n";
        }
    }
}

