#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int MOD = 1e9 + 7;

ll power(ll x, ll y, ll p) {
    ll res = 1;
    x = x % p;
    while (y > 0) {
        if (y & 1)
            res = (res * x) % p;
        y = y >> 1;
        x = (x * x) % p;
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    ll n;
    cin >> n;
    ll total_perms = power(2LL, n-1, MOD);
    ll acyclic = (n % 2 == 1) ? 1 : 2;
    for(ll k=3; k<=n; k+=2){
        ll cycles = power(n, k, MOD);
        for(ll j=1; j<=k-2; j++){
            cycles = (cycles * (n-1)) % MOD;
        }
        cycles = (cycles * power(k, MOD-2, MOD)) % MOD;
        cycles = (cycles * power(2, k-1, MOD)) % MOD;
        cyclic = (cyclic + cycles) % MOD;
    }
    ll result = (total_perms - acyclic + MOD) % MOD;
    cout << result;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, id;
    bool type;
};

int n, m;
vector<Edge> adj[500005];
bool flipped[500005];

int diameter(int u, int p, int &max_diameter, int &max_length, bool stone) {
    int max1 = 0, max2 = 0;
    for (auto &e : adj[u]) {
        if (e.to == p) continue;
        bool is_stone = e.type ^ flipped[e.id];
        int d = diameter(e.to, u, max_diameter, max_length, is_stone);
        if (is_stone) {
            if (d > max1) {
                max2 = max1;
                max1 = d;
            } else if (d > max2) {
                max2 = d;
            }
        }
    }
    int total = max1 + max2;
    if (total > max_length) {
        max_length = total;
        max_diameter = stone ? 1 : 0;
    } else if (total == max_length) {
        if (stone) max_diameter = 1;
    }
    return max1 + 1;
}

int main() {
