        cin >> u >> v >> t;
        adj[u].push_back({v, i, t == 1});
        adj[v].push_back({u, i, t == 1});
        flipped[i] = false;
    }
    cin >> m;
    int max_diameter = 0, max_length = 0;
    diameter(1, 0, max_diameter, max_length, true);
    for (int i = 0; i < m; i++) {
        int id;
        cin >> id;
        id--;
        flipped[id] = !flipped[id];
        max_diameter = 0;
        max_length = 0;
        diameter(1, 0, max_diameter, max_length, true);
        cout << (max_diameter ? max_length : max_length - 1) << '\n';
    }
}

